//! A Box tests each axis value through its Frame's Axis objects, as C's
//! does with `astAxIn` (box.c:4268), so on a sky axis a value is moved by
//! whole turns into the Box's range, and a Box that crosses RA=0 contains
//! points on both sides of it.
//!
//! `box_axin_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/box_axin_probe.c`.

#[path = "box_axin_oracle/cases.rs"]
mod cases;

use ast_core::coords::PointSet;
use ast_core::frames::{BasicFrameBuilder, CmpFrame, Frame, SkyFrame};
use ast_core::mappings::Mapping;
use ast_core::regions::{BoxRegion, BoxRegionBuilder, Region};

const D2R: f64 = std::f64::consts::PI / 180.0;

fn sky() -> SkyFrame {
    SkyFrame::unset_system()
}

fn plain(n: usize) -> ast_core::frames::BasicFrame {
    BasicFrameBuilder::new(n).build().unwrap()
}

fn cmp() -> CmpFrame {
    CmpFrame::new(Box::new(sky()), Box::new(plain(1)))
}

/// The Box from (350,-10) to (10,10) degrees, by its two corners.
fn corners(frame: impl Frame + 'static, n: usize) -> BoxRegion {
    let lo = [350.0 * D2R, -10.0 * D2R, 0.0];
    let hi = [10.0 * D2R, 10.0 * D2R, 1.0];
    BoxRegionBuilder::from_bounds(frame, &lo[..n], &hi[..n])
        .unwrap()
        .build()
        .unwrap()
}

/// The Box centered on (0,0) with a corner at (10,10) degrees.
fn centred(frame: impl Frame + 'static, n: usize) -> BoxRegion {
    let c = [0.0, 0.0, 0.5];
    let k = [10.0 * D2R, 10.0 * D2R, 1.0];
    BoxRegionBuilder::new(frame, c[..n].to_vec(), k[..n].to_vec())
        .unwrap()
        .build()
        .unwrap()
}

fn inside(region: &BoxRegion, n: usize) -> Vec<bool> {
    let lon: Vec<f64> = cases::LON.iter().map(|d| d * D2R).collect();
    let lat: Vec<f64> = cases::LAT.iter().map(|d| d * D2R).collect();
    let third = vec![0.5; lon.len()];
    let cols: Vec<&[f64]> = [&lon[..], &lat[..], &third[..]][..n].to_vec();
    let pts = PointSet::from_columns(&cols).unwrap();
    let out = region.transform(&pts, true).unwrap();
    (0..out.npoint())
        .map(|i| out.point(i)[0] != ast_core::constants::BAD_VALUE)
        .collect()
}

#[test]
fn box_containment_follows_the_c_library() {
    let mut got: Vec<(&str, Vec<bool>)> = Vec::new();
    got.push(("sky", inside(&corners(sky(), 2), 2)));
    let mut b = centred(sky(), 2);
    got.push(("sky_centred", inside(&b, 2)));
    b.negate();
    got.push(("sky_centred_negated", inside(&b, 2)));
    got.push(("plain_centred", inside(&centred(plain(2), 2), 2)));
    got.push(("cmpframe_centred", inside(&centred(cmp(), 3), 3)));
    let mut b = corners(sky(), 2);
    b.negate();
    got.push(("sky_negated", inside(&b, 2)));
    b.negate();
    b.set_closed(false);
    got.push(("sky_open", inside(&b, 2)));
    got.push(("plain", inside(&corners(plain(2), 2), 2)));
    got.push(("cmpframe", inside(&corners(cmp(), 3), 3)));

    let mut failures = Vec::new();
    assert_eq!(
        got.len(),
        cases::CASES.len(),
        "the test runs every case the C probe recorded"
    );
    for ((name, got), (want_name, want)) in got.iter().zip(cases::CASES) {
        assert_eq!(name, want_name, "the test runs the probe's cases");
        if got[..] != want[..] {
            failures.push(format!("{name}: got {got:?}, C gives {want:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
